import { createHash, constants, generateKeyPairSync, privateDecrypt } from "node:crypto"
import { describe, expect, it } from "vitest"
import {
  pqInnerDataDc,
  clientDhInnerData,
  parseServerDhInnerData,
  parseDhGenResult,
  DH_CONST,
  plainEnvelope,
  bytesToBigInt,
  rsaKeyFromBytes,
  rsaPad,
  igeDecrypt,
  TlWriter,
} from "../src/index.ts"

/** Wire vectors from core.telegram.org/mtproto/samples-auth_key. */
describe("documented handshake wire format", () => {
  const nonce = Buffer.from("51a1143fc7a3666be4be54d6890a02dc", "hex")
  const serverNonce = Buffer.from("63248f6748214eab8a2f4cc876e11974", "hex")

  it("serializes p_q_inner_data_dc exactly as documented", () => {
    const data = pqInnerDataDc(
      Buffer.from("2e9cdb98c80cda4b", "hex"),
      Buffer.from("6a794259", "hex"),
      Buffer.from("7012c543", "hex"),
      nonce,
      serverNonce,
      Buffer.from("bf8cb5bd9c5b4fe7cf24d64d281f89311576d53c0da65a83267e57315414c9a6", "hex"),
      2,
    )
    expect(Buffer.from(data).toString("hex").toUpperCase()).toBe(
      "955FF5A9082E9CDB98C80CDA4B000000046A794259000000047012C54300000051A1143FC7A3666BE4BE54D6890A02DC63248F6748214EAB8A2F4CC876E11974BF8CB5BD9C5B4FE7CF24D64D281F89311576D53C0DA65A83267E57315414C9A602000000",
    )
  })

  it("serializes client_DH_inner_data exactly as documented", () => {
    const gB = bytesToBigInt(
      Buffer.from(
        "",
        "hex",
      ),
    )
    const data = clientDhInnerData(nonce, serverNonce, 0n, gB)
    expect(Buffer.from(data).toString("hex").toUpperCase()).toBe(
      "",
    )
  })

  it("parses the documented decrypted server_DH_inner_data", () => {
    const answer = Buffer.from(
      "",
      "hex",
    )
    const parsed = parseServerDhInnerData(answer)
    expect([...parsed.nonce]).toEqual([...nonce])
    expect([...parsed.serverNonce]).toEqual([...serverNonce])
    expect(parsed.g).toBe(3)
    expect(parsed.prime.toString(16).toUpperCase().replace(/^0/, "")).toBe(
      "",
    )
    expect(parsed.serverTime).toBe(1783001185)
  })

  it("parses dh_gen_ok and distinguishes retry/fail", () => {
    const body = new TlWriter()
      .uint(DH_CONST.dhGenOk)
      .raw(nonce)
      .raw(serverNonce)
      .raw(Buffer.from("aa404b58df404d8f363772b14ce5a56f", "hex"))
      .result()
    const parsed = parseDhGenResult(plainEnvelope(body, 1n))
    expect(parsed.kind).toBe("ok")
    expect([...parsed.value.newNonceHash1]).toEqual([...Buffer.from("aa404b58df404d8f363772b14ce5a56f", "hex")])
  })

  it("rsaPad produces a recoverable padded payload", async () => {
    const { privateKey, publicKey } = generateKeyPairSync("rsa", { modulusLength: 2048 })
    const jwk = publicKey.export({ format: "jwk" }) as { n: string; e: string }
    const key = await rsaKeyFromBytes(Buffer.from(jwk.n, "base64url"), Buffer.from(jwk.e, "base64url"))
    const data = Buffer.from("reqly rsa pad vector", "utf8")
    const encrypted = await rsaPad(data, key)
    expect(encrypted.length).toBe(256)

    const decrypted = privateDecrypt({ key: privateKey, padding: constants.RSA_NO_PADDING }, Buffer.from(encrypted))
    const tempKeyXor = decrypted.subarray(0, 32)
    const aes = decrypted.subarray(32)
    const digest = createHash("sha256").update(Buffer.from(aes)).digest()
    const tempKey = Buffer.from(tempKeyXor).map((byte, index) => byte ^ (digest[index] ?? 0))
    const padded = igeDecrypt(aes, tempKey, new Uint8Array(32))
    const dataWithPadding = Buffer.from(padded.subarray(0, 192)).reverse()
    expect(dataWithPadding.subarray(0, data.length)).toEqual(data)
    expect(Buffer.from(padded.subarray(192))).toEqual(createHash("sha256").update(Buffer.concat([tempKey, dataWithPadding])).digest())
  })
})
